/* DoorLock: switch-based hierarchical state machine generated by MachinaState (C99). Do not edit by hand. */
#include "DoorLock.h"

/* Internal functions */
static size_t RegionOf(Security_DoorLock_State state);
static size_t FirstRegionOf(Security_DoorLock_State state);
static size_t RegionsOf(Security_DoorLock_State state);
static void Trace(Security_DoorLock* m, Security_DoorLock_TraceKind kind, const char* name);
static void OnEntry(Security_DoorLock* m, Security_DoorLock_State state);
static void OnExit(Security_DoorLock* m, Security_DoorLock_State state);
static Security_DoorLock_State Innermost(const Security_DoorLock* m, Security_DoorLock_State state);
static void ExitState(Security_DoorLock* m, Security_DoorLock_State state);
static void EnterState(Security_DoorLock* m, Security_DoorLock_State state);
static void EnterRegion(Security_DoorLock* m, size_t region);
static void EnterDefault(Security_DoorLock* m, Security_DoorLock_State state);
static void EnterDown(Security_DoorLock* m, Security_DoorLock_State from, Security_DoorLock_State target);
static bool HandleEvent(Security_DoorLock* m, Security_DoorLock_State state, Security_DoorLock_Event event);
static bool DispatchState(Security_DoorLock* m, Security_DoorLock_State state, Security_DoorLock_Event event);
static bool DispatchCore(Security_DoorLock* m, Security_DoorLock_Event event);
static bool Enqueue(Security_DoorLock* m, const Security_DoorLock_QueuedEvent* entry);
static void DrainQueue(Security_DoorLock* m);

static size_t RegionOf(Security_DoorLock_State state) {
    (void)state;
    return 0;
}

static size_t FirstRegionOf(Security_DoorLock_State state) {
    (void)state;
    return 0;
}

static size_t RegionsOf(Security_DoorLock_State state) {
    (void)state;
    return 0;
}

Security_DoorLock_State Security_DoorLock_ParentOf(Security_DoorLock_State state) {
    (void)state;
    return Security_DoorLock_State_None;
}

const char* Security_DoorLock_StateName(Security_DoorLock_State state) {
    switch (state) {
        case Security_DoorLock_State_Locked:
            return "Locked";
        case Security_DoorLock_State_Unlocked:
            return "Unlocked";
        case Security_DoorLock_State_Alarm:
            return "Alarm";
        default:
            return "None";
    }
}

const char* Security_DoorLock_EventName(Security_DoorLock_Event event) {
    switch (event) {
        case Security_DoorLock_Event_EnterCode:
            return "EnterCode";
        case Security_DoorLock_Event_Lock:
            return "Lock";
        case Security_DoorLock_Event_Timeout:
            return "Timeout";
        case Security_DoorLock_Event_Reset:
            return "Reset";
        default:
            return "";
    }
}

static void Trace(Security_DoorLock* m, Security_DoorLock_TraceKind kind, const char* name) {
    if (m->hooks->Trace != NULL) {
        m->hooks->Trace(m->context, kind, name);
    }
}

static void OnEntry(Security_DoorLock* m, Security_DoorLock_State state) {
    switch (state) {
        case Security_DoorLock_State_Locked:
            m->hooks->engageBolt(m->context);
            break;
        case Security_DoorLock_State_Unlocked:
            m->hooks->releaseBolt(m->context);
            break;
        case Security_DoorLock_State_Alarm:
            m->hooks->sirenOn(m->context);
            break;
        default:
            break;
    }
}

static void OnExit(Security_DoorLock* m, Security_DoorLock_State state) {
    switch (state) {
        case Security_DoorLock_State_Alarm:
            m->hooks->sirenOff(m->context);
            break;
        default:
            break;
    }
}

static Security_DoorLock_State Innermost(const Security_DoorLock* m, Security_DoorLock_State state) {
    while (state != Security_DoorLock_State_None && RegionsOf(state) > 0 && m->active[FirstRegionOf(state)] != Security_DoorLock_State_None) {
        state = m->active[FirstRegionOf(state)];
    }
    return state;
}

static void ExitState(Security_DoorLock* m, Security_DoorLock_State state) {
    size_t region;
    for (region = FirstRegionOf(state) + RegionsOf(state); region-- > FirstRegionOf(state);) {
        if (m->active[region] != Security_DoorLock_State_None) {
            ExitState(m, m->active[region]);
        }
    }
    Trace(m, Security_DoorLock_Trace_Exit, Security_DoorLock_StateName(state));
    OnExit(m, state);
    m->active[RegionOf(state)] = Security_DoorLock_State_None;
}

static void EnterState(Security_DoorLock* m, Security_DoorLock_State state) {
    m->active[RegionOf(state)] = state;
    Trace(m, Security_DoorLock_Trace_Enter, Security_DoorLock_StateName(state));
    OnEntry(m, state);
}

static void EnterRegion(Security_DoorLock* m, size_t region) {
    (void)m;
    (void)region;
}

static void EnterDefault(Security_DoorLock* m, Security_DoorLock_State state) {
    size_t region;
    for (region = FirstRegionOf(state); region < FirstRegionOf(state) + RegionsOf(state); ++region) {
        EnterRegion(m, region);
    }
}

static void EnterDown(Security_DoorLock* m, Security_DoorLock_State from, Security_DoorLock_State target) {
    Security_DoorLock_State state = target;
    Security_DoorLock_State next = Security_DoorLock_State_None;
    while (Security_DoorLock_ParentOf(state) != from) {
        next = state;
        state = Security_DoorLock_ParentOf(state);
    }
    EnterState(m, state);
    if (next == Security_DoorLock_State_None) {
        EnterDefault(m, state);
        return;
    }
    EnterDown(m, state, target);
}

static bool HandleEvent(Security_DoorLock* m, Security_DoorLock_State state, Security_DoorLock_Event event) {
    switch (state) {
        case Security_DoorLock_State_Locked:
            switch (event) {
                case Security_DoorLock_Event_EnterCode:
                    if (m->hooks->isValidCode(m->context, ((const Security_DoorLock_EnterCodeArgs*)m->args)->code)) {
                        Trace(m, Security_DoorLock_Trace_Transition, "Locked -> Unlocked");
                        ExitState(m, Security_DoorLock_State_Locked);
                        m->hooks->resetAttempts(m->context, ((const Security_DoorLock_EnterCodeArgs*)m->args)->code);
                        EnterDown(m, Security_DoorLock_State_None, Security_DoorLock_State_Unlocked);
                        return true;
                    }
                    if (m->hooks->tooManyAttempts(m->context, ((const Security_DoorLock_EnterCodeArgs*)m->args)->code)) {
                        Trace(m, Security_DoorLock_Trace_Transition, "Locked -> Alarm");
                        ExitState(m, Security_DoorLock_State_Locked);
                        EnterDown(m, Security_DoorLock_State_None, Security_DoorLock_State_Alarm);
                        return true;
                    }
                    Trace(m, Security_DoorLock_Trace_Transition, "Locked (internal)");
                    m->hooks->countFailure(m->context, ((const Security_DoorLock_EnterCodeArgs*)m->args)->code);
                    return true;
                default:
                    break;
            }
            break;
        case Security_DoorLock_State_Unlocked:
            switch (event) {
                case Security_DoorLock_Event_Lock:
                    Trace(m, Security_DoorLock_Trace_Transition, "Unlocked -> Locked");
                    ExitState(m, Security_DoorLock_State_Unlocked);
                    EnterDown(m, Security_DoorLock_State_None, Security_DoorLock_State_Locked);
                    return true;
                case Security_DoorLock_Event_Timeout:
                    Trace(m, Security_DoorLock_Trace_Transition, "Unlocked -> Locked");
                    ExitState(m, Security_DoorLock_State_Unlocked);
                    EnterDown(m, Security_DoorLock_State_None, Security_DoorLock_State_Locked);
                    return true;
                default:
                    break;
            }
            break;
        case Security_DoorLock_State_Alarm:
            switch (event) {
                case Security_DoorLock_Event_Reset:
                    if (m->hooks->isAdminCode(m->context, ((const Security_DoorLock_ResetArgs*)m->args)->code)) {
                        Trace(m, Security_DoorLock_Trace_Transition, "Alarm -> Locked");
                        ExitState(m, Security_DoorLock_State_Alarm);
                        m->hooks->resetAttempts(m->context, ((const Security_DoorLock_ResetArgs*)m->args)->code);
                        EnterDown(m, Security_DoorLock_State_None, Security_DoorLock_State_Locked);
                        return true;
                    }
                    break;
                default:
                    break;
            }
            break;
        default:
            break;
    }
    return false;
}

/* Offers the event to every active region below `state` first, then to `state` itself. */
static bool DispatchState(Security_DoorLock* m, Security_DoorLock_State state, Security_DoorLock_Event event) {
    size_t region;
    for (region = FirstRegionOf(state); region < FirstRegionOf(state) + RegionsOf(state); ++region) {
        if (m->active[region] != Security_DoorLock_State_None && DispatchState(m, m->active[region], event)) {
            return true;
        }
    }
    return HandleEvent(m, state, event);
}

static bool DispatchCore(Security_DoorLock* m, Security_DoorLock_Event event) {
    Trace(m, Security_DoorLock_Trace_Event, Security_DoorLock_EventName(event));
    if (m->active[0] != Security_DoorLock_State_None && DispatchState(m, m->active[0], event)) {
        return true;
    }
    Trace(m, Security_DoorLock_Trace_Ignored, Security_DoorLock_EventName(event));
    return false;
}

static bool Enqueue(Security_DoorLock* m, const Security_DoorLock_QueuedEvent* entry) {
    if (m->queueCount == Security_DoorLock_QueueCapacity) {
        return false;
    }
    m->queue[(m->queueHead + m->queueCount) % Security_DoorLock_QueueCapacity] = *entry;
    ++m->queueCount;
    return true;
}

static void DrainQueue(Security_DoorLock* m) {
    while (m->queueCount > 0) {
        const Security_DoorLock_QueuedEvent entry = m->queue[m->queueHead];
        m->queueHead = (m->queueHead + 1) % Security_DoorLock_QueueCapacity;
        --m->queueCount;
        m->args = &entry.args;
        DispatchCore(m, entry.event);
        m->args = NULL;
    }
}

void Security_DoorLock_Init(Security_DoorLock* m, const Security_DoorLock_Hooks* hooks, void* context) {
    size_t i;
    m->hooks   = hooks;
    m->context = context;
    for (i = 0; i < Security_DoorLock_RegionCount; ++i) {
        m->active[i] = Security_DoorLock_State_None;
    }
    m->queueHead  = 0;
    m->queueCount = 0;
    m->args = NULL;
}

void Security_DoorLock_Start(Security_DoorLock* m) {
    size_t i;
    m->hooks->Lock(m->context);
    for (i = 0; i < Security_DoorLock_RegionCount; ++i) {
        m->active[i] = Security_DoorLock_State_None;
    }
    m->queueHead  = 0;
    m->queueCount = 0;
    Trace(m, Security_DoorLock_Trace_Start, "DoorLock");
    EnterDown(m, Security_DoorLock_State_None, Security_DoorLock_State_Locked);
    DrainQueue(m);
    m->hooks->Unlock(m->context);
}

bool Security_DoorLock_Dispatch(Security_DoorLock* m, Security_DoorLock_Event event) {
    bool handled = false;
    m->hooks->Lock(m->context);
    if (event != Security_DoorLock_Event_EnterCode && event != Security_DoorLock_Event_Reset) {
        m->args = NULL;
        handled = DispatchCore(m, event);
        m->args = NULL;
        DrainQueue(m);
    }
    m->hooks->Unlock(m->context);
    return handled;
}

bool Security_DoorLock_DispatchEnterCode(Security_DoorLock* m, int code) {
    bool handled;
    Security_DoorLock_EnterCodeArgs args;
    args.code = code;
    m->hooks->Lock(m->context);
    m->args = &args;
    handled = DispatchCore(m, Security_DoorLock_Event_EnterCode);
    m->args = NULL;
    DrainQueue(m);
    m->hooks->Unlock(m->context);
    return handled;
}

bool Security_DoorLock_DispatchReset(Security_DoorLock* m, int code) {
    bool handled;
    Security_DoorLock_ResetArgs args;
    args.code = code;
    m->hooks->Lock(m->context);
    m->args = &args;
    handled = DispatchCore(m, Security_DoorLock_Event_Reset);
    m->args = NULL;
    DrainQueue(m);
    m->hooks->Unlock(m->context);
    return handled;
}

bool Security_DoorLock_Post(Security_DoorLock* m, Security_DoorLock_Event event) {
    Security_DoorLock_QueuedEvent entry;
    if (!(event != Security_DoorLock_Event_EnterCode && event != Security_DoorLock_Event_Reset)) {
        return false;
    }
    entry.event = event;
    return Enqueue(m, &entry);
}

bool Security_DoorLock_PostEnterCode(Security_DoorLock* m, int code) {
    Security_DoorLock_QueuedEvent entry;
    entry.event = Security_DoorLock_Event_EnterCode;
    entry.args.EnterCode.code = code;
    return Enqueue(m, &entry);
}

bool Security_DoorLock_PostReset(Security_DoorLock* m, int code) {
    Security_DoorLock_QueuedEvent entry;
    entry.event = Security_DoorLock_Event_Reset;
    entry.args.Reset.code = code;
    return Enqueue(m, &entry);
}

Security_DoorLock_State Security_DoorLock_Current(const Security_DoorLock* m) {
    Security_DoorLock_State result;
    m->hooks->Lock(m->context);
    result = Innermost(m, m->active[0]);
    m->hooks->Unlock(m->context);
    return result;
}

bool Security_DoorLock_IsIn(const Security_DoorLock* m, Security_DoorLock_State state) {
    bool result;
    m->hooks->Lock(m->context);
    result = state != Security_DoorLock_State_None && m->active[RegionOf(state)] == state;
    m->hooks->Unlock(m->context);
    return result;
}

bool Security_DoorLock_IsFinished(const Security_DoorLock* m) {
    bool result;
    m->hooks->Lock(m->context);
    result = ((void)m, false);
    m->hooks->Unlock(m->context);
    return result;
}

